/// <reference path="../../../src/workflow-defs.d.ts" />

export const name: string = "read-then-optimize";

export const description: string =
  "Two-phase optimization: Phase 1 reads ALL files and produces a structured analysis " +
  "(constraints, inefficiencies, planned changes). Phase 2 executes the plan, writes " +
  "the report, and verifies every change. Prevents blind edits and skipped verification.";

export async function execute(ctx: WorkflowContext): Promise<WorkflowResult> {
  // ── Phase 1: Read & Analyze ──────────────────────────────────────────
  // The optimizer reads every relevant file and produces a structured
  // analysis BEFORE any edits happen. This prevents FM-2.1 (blind edits
  // that violate constraints discovered too late).

  const phase1Task =
    `## PHASE 1 — READ & ANALYZE ONLY (do NOT edit any files)\n\n` +
    `### Original Task\n${ctx.task}\n\n` +
    `### Your Job in This Phase\n` +
    `1. Read EVERY file mentioned in the task (configs, READMEs, docs — all of them)\n` +
    `2. Identify ALL constraints that must be preserved (immutable values, relationships, etc.)\n` +
    `3. Identify ALL inefficiencies, redundancies, and suboptimal settings\n` +
    `4. For each planned change, specify: which file, what line/section, current value → new value\n` +
    `5. Note anything you must NOT change and why\n\n` +
    `### Output Format\n` +
    `Write your analysis as a structured report with these sections:\n` +
    `- **CONSTRAINTS** — list every constraint you found, with the source file and exact text\n` +
    `- **INEFFICIENCIES** — list every issue found, with file, current value, and why it's suboptimal\n` +
    `- **CHANGE PLAN** — for each change: file, section, current → proposed, and which constraint it respects\n` +
    `- **DO NOT TOUCH** — things that must remain unchanged, with reasoning\n\n` +
    `⚠️ DO NOT edit, write, or create any files. Read-only analysis phase.\n` +
    `⚠️ If the task mentions a report to write, plan its contents but do NOT write it yet.`;

  const analysis = await ctx.runAgent("optimizer", phase1Task);
  if (analysis.status === "error") {
    return ctx.escalate("Phase 1 (analysis) failed", { error: analysis.error });
  }

  const analysisText = analysis.lastAssistantText ?? "";

  // ── Phase 2: Execute & Verify ────────────────────────────────────────
  // The optimizer now applies the planned changes, writes any required
  // reports, and verifies every edit by reading files back. This prevents
  // FM-3.3 (skipped verification).

  const phase2Task =
    `## PHASE 2 — EXECUTE CHANGES & VERIFY\n\n` +
    `### Original Task\n${ctx.task}\n\n` +
    `### Phase 1 Analysis (your analysis from the read phase)\n${analysisText}\n\n` +
    `### Your Job in This Phase\n` +
    `1. Execute EVERY change from the CHANGE PLAN above — edit each file precisely as planned\n` +
    `2. Respect EVERY constraint from the CONSTRAINTS section — do not modify protected values\n` +
    `3. Write the optimization report (if the task requires one) — include what changed, what didn't, and why\n` +
    `4. VERIFY: After ALL edits, read back EVERY file you modified and confirm:\n` +
    `   - Each planned change was applied correctly\n` +
    `   - No constraint was violated\n` +
    `   - The report exists and is complete\n\n` +
    `⚠️ Do NOT skip the verification step — read back every modified file.\n` +
    `⚠️ If you discover a constraint violation during verification, fix it immediately.\n` +
    `⚠️ The report file is a REQUIRED deliverable — do not skip it.`;

  const execution = await ctx.runAgent("optimizer", phase2Task);
  if (execution.status === "error") {
    return ctx.escalate("Phase 2 (execution) failed", { error: execution.error });
  }

  const executionText = execution.lastAssistantText ?? "";

  return ctx.done(
    `## Two-Phase Optimization Complete\n\n` +
    `### Phase 1 — Analysis\n${analysisText}\n\n` +
    `### Phase 2 — Execution & Verification\n${executionText}`
  );
}

